# display.ps1 (19 Nov, Strategy/COO): native resolution of the primary display for the packaged launchers (DPI-aware, not hard-coded).
function Get-NativeRes { try { Add-Type -Namespace FkDisp -Name W -MemberDefinition '[System.Runtime.InteropServices.DllImport("user32.dll")] public static extern bool SetProcessDPIAware(); [System.Runtime.InteropServices.DllImport("user32.dll")] public static extern int GetSystemMetrics(int n);' -ErrorAction Stop } catch { }; try { [void][FkDisp.W]::SetProcessDPIAware(); $w = [FkDisp.W]::GetSystemMetrics(0); $h = [FkDisp.W]::GetSystemMetrics(1); if ($w -ge 800 -and $h -ge 600) { return @($w, $h) } } catch { }; return @(1920, 1080) }
# Test-SavedRes: true when the player already has a saved resolution (settings.json resW/resH > 0 in the save dir): then the launcher passes NO size args so the saved choice survives (COO 19 Nov).
function Test-SavedRes([string]$dir) { try { $f = Join-Path $dir 'settings.json'; if (Test-Path -LiteralPath $f) { $j = (Get-Content -LiteralPath $f -Raw).TrimStart([char]0xFEFF) | ConvertFrom-Json; return ([int]$j.resW -gt 0 -and [int]$j.resH -gt 0) } } catch { }; return $false }
